<?php
require_once __DIR__.'/includes/functions.php';require_login();require_once __DIR__.'/config/database.php';$pageTitle='Reports';$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');
$q=$pdo->prepare('SELECT COUNT(*) AS sale_count,COALESCE(SUM(total_amount),0) AS revenue FROM sales WHERE sale_date >= ? AND sale_date < DATE_ADD(?, INTERVAL 1 DAY)');$q->execute([$from,$to]);$summary=$q->fetch();
$q=$pdo->prepare('SELECT s.invoice_no,s.sale_date,s.total_amount,s.payment_method,c.full_name AS customer_name FROM sales s LEFT JOIN customers c ON c.id=s.customer_id WHERE s.sale_date >= ? AND s.sale_date < DATE_ADD(?, INTERVAL 1 DAY) ORDER BY s.sale_date DESC');$q->execute([$from,$to]);$rows=$q->fetchAll();
$q=$pdo->prepare('SELECT p.name,p.sku,SUM(si.quantity) AS units_sold,SUM(si.line_total) AS revenue FROM sale_items si JOIN sales s ON s.id=si.sale_id JOIN products p ON p.id=si.product_id WHERE s.sale_date >= ? AND s.sale_date < DATE_ADD(?, INTERVAL 1 DAY) GROUP BY p.id,p.name,p.sku ORDER BY units_sold DESC LIMIT 10');$q->execute([$from,$to]);$topProducts=$q->fetchAll();require __DIR__.'/includes/header.php';
?>
<div class="card"><div class="card-header"><h3 class="card-title"><i class="fas fa-filter mr-1"></i> Filter report period</h3></div><div class="card-body"><form method="get" class="form-inline"><label class="mr-2">From</label><input type="date" name="from" class="form-control mr-3 mb-2" value="<?=e($from)?>" required><label class="mr-2">To</label><input type="date" name="to" class="form-control mr-3 mb-2" value="<?=e($to)?>" required><button class="btn btn-primary mb-2"><i class="fas fa-search mr-1"></i> Generate</button><button type="button" onclick="window.print()" class="btn btn-default ml-2 mb-2"><i class="fas fa-print mr-1"></i> Print</button></form></div></div>
<div class="row"><div class="col-md-6"><div class="small-box bg-success"><div class="inner"><h3><?=money($summary['revenue'])?></h3><p>Revenue (TZS) · <?=e($from)?> to <?=e($to)?></p></div><div class="icon"><i class="fas fa-money-bill-wave"></i></div></div></div><div class="col-md-6"><div class="small-box bg-info"><div class="inner"><h3><?=(int)$summary['sale_count']?></h3><p>Number of sales</p></div><div class="icon"><i class="fas fa-receipt"></i></div></div></div></div>
<div class="row"><div class="col-lg-7"><div class="card"><div class="card-header"><h3 class="card-title">Sales Transactions</h3></div><div class="card-body table-responsive p-0"><table class="table table-hover"><thead><tr><th>Invoice</th><th>Date</th><th>Customer</th><th>Payment</th><th>Total (TZS)</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty-state">No sales found for this period.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['invoice_no'])?></td><td><?=e(date('d/m/Y H:i',strtotime($r['sale_date'])))?></td><td><?=e($r['customer_name']?:'Walk-in')?></td><td><?=e($r['payment_method'])?></td><td><?=money($r['total_amount'])?></td></tr><?php endforeach;endif;?></tbody></table></div></div></div><div class="col-lg-5"><div class="card"><div class="card-header"><h3 class="card-title">Top Products by Units Sold</h3></div><div class="card-body table-responsive p-0"><table class="table table-hover"><thead><tr><th>Product</th><th>Units</th><th>Revenue</th></tr></thead><tbody><?php if(!$topProducts):?><tr><td colspan="3" class="empty-state">No product sales yet.</td></tr><?php else:foreach($topProducts as $p):?><tr><td><?=e($p['name'])?><br><small><?=e($p['sku'])?></small></td><td><?=(int)$p['units_sold']?></td><td><?=money($p['revenue'])?></td></tr><?php endforeach;endif;?></tbody></table></div></div></div></div>
<?php require __DIR__.'/includes/footer.php';?>
